python3 << 'PYEOF'
import json

# Load the IxP registry get result
with open('/home/azureuser/.claude/projects/-work-output-artifacts-skill-flow-ixp-routing-receipts/c99613cb-e3eb-4e44-af72-a643091be35a/tool-results/bd6713v9l.txt') as f:
    ixp_registry = json.load(f)

ixp_node_def = ixp_registry['Data']['Node']
ixp_defaults = ixp_node_def['inputDefaults']
ixp_output_def = ixp_node_def['outputDefinition']

# modelName is null — use modelDisplayName
model_name = ixp_defaults['model']['modelName'] or ixp_defaults['model']['modelDisplayName']

flow = {
  "id": "c673c058-f086-4073-8062-a91d64404c61",
  "version": "1.8",
  "name": "ReceiptsFlow",
  "nodes": [
    {
      "id": "start",
      "type": "core.trigger.manual",
      "typeVersion": "1.0",
      "display": { "label": "Manual trigger" },
      "inputs": {
        "entryPointId": "a5fc825c-7d07-4110-a4b8-5f739248bae2",
        "isDefaultEntryPoint": True
      }
    },
    {
      "id": "extractReceiptFields",
      "type": ixp_node_def['nodeType'],
      "typeVersion": ixp_node_def['version'],
      "display": { "label": "Extract Receipt Fields" },
      "inputs": {
        "model": {
          "id": ixp_defaults['model']['id'],
          "modelName": model_name,
          "modelDisplayName": ixp_defaults['model']['modelDisplayName'],
          "folderKey": ixp_defaults['model']['folderKey'],
          "folderName": ixp_defaults['model']['folderName'],
          "folderPath": ixp_defaults['model']['folderPath'],
          "description": ixp_defaults['model']['description']
        },
        "modelName": ixp_defaults['modelName'],
        "description": ixp_defaults.get('description', ''),
        "projectName": ixp_defaults['projectName'],
        "versionTag": ixp_defaults['versionTag'],
        "folderKey": ixp_defaults['folderKey'],
        "folderName": ixp_defaults['folderName'],
        "fileRef": "=js:$vars.start.output.receiptFile",
        "pageRange": ixp_defaults['pageRange']
      },
      "outputs": {
        "output": ixp_output_def['output'],
        "error": ixp_output_def['error']
      }
    },
    {
      "id": "parseReceipt",
      "type": "core.action.script",
      "typeVersion": "1.0",
      "display": { "label": "Parse merchant, date, total" },
      "inputs": {
        "script": (
          "const fields = ($vars.extractReceiptFields.output.ExtractionResult"
          " && $vars.extractReceiptFields.output.ExtractionResult.ResultsDocument"
          " && $vars.extractReceiptFields.output.ExtractionResult.ResultsDocument.Fields) || [];\n"
          "const find = (names) => {\n"
          "  const hit = fields.find(f => names.includes(f.FieldName));\n"
          "  return hit && hit.Values && hit.Values[0] ? hit.Values[0] : '';\n"
          "};\n"
          "const merchant = find(['merchant_name', 'Merchant', 'vendor', 'store_name', 'Vendor']);\n"
          "const date = find(['purchase_date', 'Date', 'transaction_date', 'date', 'receipt_date']);\n"
          "const total = find(['total_amount', 'Total', 'total', 'amount', 'Amount', 'grand_total']);\n"
          "return { merchant, date, total };"
        )
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "The return value of the script",
          "source": "=result.response",
          "var": "output"
        }
      }
    },
    {
      "id": "end",
      "type": "core.control.end",
      "typeVersion": "1.0",
      "display": { "label": "End" },
      "inputs": {},
      "outputs": {
        "merchant": { "source": "=js:$vars.parseReceipt.output.merchant" },
        "date": { "source": "=js:$vars.parseReceipt.output.date" },
        "total": { "source": "=js:$vars.parseReceipt.output.total" }
      }
    }
  ],
  "edges": [
    {
      "id": "e-start-extract",
      "source": "start",
      "target": "extractReceiptFields",
      "sourceHandle": "output",
      "targetHandle": "input",
      "targetPort": "input"
    },
    {
      "id": "e-extract-parse",
      "source": "extractReceiptFields",
      "target": "parseReceipt",
      "sourceHandle": "success",
      "targetHandle": "input",
      "targetPort": "input"
    },
    {
      "id": "e-parse-end",
      "source": "parseReceipt",
      "target": "end",
      "sourceHandle": "success",
